# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorLog {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface Props {
  children: ReactNode;
  fallback?: ReactNode | ((props: FallbackProps) => ReactNode);
  onError?: (log: ErrorLog) => void;
  onReset?: () => void;
  resetKeys?: unknown[];
  isolate?: boolean;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  errorCount: number;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  resetError: () => void;
  errorCount: number;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

class ErrorLogger {
  private static logs: ErrorLog[] = [];

  static log(error: Error, errorInfo: ErrorInfo): ErrorLog {
    const entry: ErrorLog = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? "",
    };

    this.logs.push(entry);

    // Console output with grouping
    console.group(
      `%c⚠ React Error Boundary [${entry.timestamp.toISOString()}]`,
      "color: #ff4444; font-weight: bold;"
    );
    console.error("Error:", error.message);
    console.error("Stack:", error.stack);
    console.error("Component Stack:", entry.componentStack);
    console.groupEnd();

    return entry;
  }

  static getLogs(): ErrorLog[] {
    return [...this.logs];
  }

  static clearLogs(): void {
    this.logs = [];
  }
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

const DefaultFallback: React.FC<FallbackProps> = ({
  error,
  errorInfo,
  resetError,
  errorCount,
}) => {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper}>
          <svg
            style={styles.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Heading */}
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.subheading}>
          {errorCount > 1
            ? `This component has crashed ${errorCount} times.`
            : "An unexpected error occurred in this component."}
        </p>

        {/* Error message */}
        <div style={styles.errorMessage}>
          <code style={styles.errorCode}>{error.message}</code>
        </div>

        {/* Actions */}
        <div style={styles.actions}>
          <button style={styles.retryButton} onClick={resetError}>
            ↺ Try Again
          </button>
          <button
            style={styles.detailsButton}
            onClick={() => setShowDetails((v) => !v)}
          >
            {showDetails ? "Hide" : "Show"} Details
          </button>
        </div>

        {/* Collapsible details */}
        {showDetails && (
          <details open style={styles.details}>
            <summary style={styles.summary}>Stack Trace</summary>
            <pre style={styles.pre}>{error.stack}</pre>
            <summary style={styles.summary}>Component Stack</summary>
            <pre style={styles.pre}>{errorInfo.componentStack}</pre>
          </details>
        )}
      </div>
    </div>
  );
};

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "200px",
    padding: "24px",
    fontFamily: "system-ui, -apple-system, sans-serif",
  },
  card: {
    background: "#fff",
    border: "1px solid #fee2e2",
    borderRadius: "12px",
    boxShadow: "0 4px 24px rgba(239,68,68,0.08)",
    maxWidth: "560px",
    width: "100%",
    padding: "32px",
    textAlign: "center",
  },
  iconWrapper: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "16px",
  },
  icon: {
    width: "48px",
    height: "48px",
    color: "#ef4444",
  },
  heading: {
    margin: "0 0 8px",
    fontSize: "20px",
    fontWeight: 700,
    color: "#111827",
  },
  subheading: {
    margin: "0 0 20px",
    fontSize: "14px",
    color: "#6b7280",
  },
  errorMessage: {
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "8px",
    padding: "12px 16px",
    marginBottom: "24px",
    textAlign: "left",
  },
  errorCode: {
    fontSize: "13px",
    color: "#dc2626",
    wordBreak: "break-word",
    fontFamily: "monospace",
  },
  actions: {
    display: "flex",
    gap: "12px",
    justifyContent: "center",
    marginBottom: "16px",
  },
  retryButton: {
    background: "#ef4444",
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "14px",
    fontWeight: 600,
    cursor: "pointer",
    transition: "background 0.2s",
  },
  detailsButton: {
    background: "transparent",
    color: "#6b7280",
    border: "1px solid #d1d5db",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "14px",
    fontWeight: 500,
    cursor: "pointer",
  },
  details: {
    textAlign: "left",
    marginTop: "16px",
  },
  summary: {
    fontSize: "12px",
    fontWeight: 600,
    color: "#374151",
    cursor: "pointer",
    marginBottom: "8px",
    display: "block",
  },
  pre: {
    background: "#f9fafb",
    border: "1px solid #e5e7eb",
    borderRadius: "6px",
    padding: "12px",
    fontSize: "11px",
    color: "#374151",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    marginBottom: "12px",
  },
};

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends Component<Props, State> {
  static defaultProps: Partial<Props> = {
    resetKeys: [],
    isolate: false,
  };

  state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
    errorCount: 0,
  };

  // Triggered during render phase — update state to show fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Triggered after render — side effects (logging, callbacks)
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const log = ErrorLogger.log(error, errorInfo);

    this.setState((prev) => ({
      errorInfo,
      errorCount: prev.errorCount + 1,
    }));

    this.props.onError?.(log);
  }

  // Watch resetKeys for external reset triggers
  componentDidUpdate(prevProps: Props): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (
      hasError &&
      resetKeys?.length &&
      resetKeys.some((key, i) => key !== prevProps.resetKeys?.[i])
    ) {
      this.resetError();
    }
  }

  resetError = (): void => {
    this.props.onReset?.();
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      // Keep errorCount for tracking repeated failures
    });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo, errorCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && error && errorInfo) {
      const fallbackProps: FallbackProps = {
        error,
        errorInfo,
        resetError: this.resetError,
        errorCount,
      };

      // Custom fallback: render-prop or ReactNode
      if (typeof fallback === "function") {
        return fallback(fallbackProps);
      }
      if (fallback) {
        return fallback;
      }

      // Default fallback UI
      return <DefaultFallback {...fallbackProps} />;
    }

    // isolate=true wraps children to prevent cascade
    return isolate ? <React.Fragment>{children}</React.Fragment> : children;
  }
}

export { ErrorBoundary, ErrorLogger };
export type { ErrorLog, Props as ErrorBoundaryProps };
