## Usage Examples

```tsx
// App.tsx
import React, { useState } from "react";
import { ErrorBoundary, ErrorLogger, FallbackProps } from "./ErrorBoundary";

// ─── Buggy Component ──────────────────────────────────────────────────────────

const BuggyCounter: React.FC = () => {
  const [count, setCount] = useState(0);

  if (count === 3) {
    throw new Error(`Counter exploded at value: ${count}`);
  }

  return (
    <div style={{ textAlign: "center", padding: "20px" }}>
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>
        Increment (crashes at 3)
      </button>
    </div>
  );
};

// ─── Example 1: Default fallback ──────────────────────────────────────────────

export const BasicExample: React.FC = () => (
  <ErrorBoundary
    onError={(log) => {
      // Send to your error tracking service (Sentry, Datadog, etc.)
      console.log("Captured error log:", log.timestamp);
    }}
  >
    <BuggyCounter />
  </ErrorBoundary>
);

// ─── Example 2: Custom render-prop fallback ───────────────────────────────────

const CustomFallback = ({ error, resetError, errorCount }: FallbackProps) => (
  <div
    style={{
      padding: "20px",
      background: "#1e1e2e",
      color: "#cdd6f4",
      borderRadius: "8px",
    }}
  >
    <h3 style={{ color: "#f38ba8" }}>💥 Oops! {error.message}</h3>
    <p style={{ color: "#a6adc8", fontSize: "13px" }}>
      Crashed {errorCount} time(s)
    </p>
    <button
      onClick={resetError}
      style={{
        background: "#89b4fa",
        color: "#1e1e2e",
        border: "none",
        padding: "8px 16px",
        borderRadius: "6px",
        cursor: "pointer",
      }}
    >
      Retry
    </button>
  </div>
);

export const CustomFallbackExample: React.FC = () => (
  <ErrorBoundary fallback={(props) => <CustomFallback {...props} />}>
    <BuggyCounter />
  </ErrorBoundary>
);

// ─── Example 3: resetKeys — auto-reset when prop changes ─────────────────────

export const ResetKeysExample: React.FC = () => {
  const [userId, setUserId] = useState(1);

  return (
    <div>
      <button onClick={() => setUserId((id) => id + 1)}>
        Load User #{userId + 1} (resets boundary)
      </button>
      <ErrorBoundary
        resetKeys={[userId]}
        onReset={() => console.log("Boundary reset due to userId change")}
      >
        <BuggyCounter key={userId} />
      </ErrorBoundary>
    </div>
  );
};

// ─── Example 4: Nested / isolated boundaries ─────────────────────────────────

export const NestedExample: React.FC = () => (
  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "16px" }}>
    <ErrorBoundary isolate>
      <BuggyCounter />
    </ErrorBoundary>
    <ErrorBoundary isolate>
      <BuggyCounter />
    </ErrorBoundary>
  </div>
);

// ─── Example 5: Access error logs ────────────────────────────────────────────

export const LogsExample: React.FC = () => {
  const [logs, setLogs] = useState(ErrorLogger.getLogs());

  return (
    <div>
      <ErrorBoundary onError={() => setLogs(ErrorLogger.getLogs())}>
        <BuggyCounter />
      </ErrorBoundary>
      <div style={{ marginTop: "16px" }}>
        <h4>Error Logs ({logs.length})</h4>
        {logs.map((log, i) => (
          <div
            key={i}
            style={{
              background: "#fef2f2",
              padding: "8px",
              borderRadius: "4px",
              marginBottom: "4px",
              fontSize: "12px",
            }}
          >
            [{log.timestamp.toLocaleTimeString()}] {log.error.message}
          </div>
        ))}
        <button onClick={() => { ErrorLogger.clearLogs(); setLogs([]); }}>
          Clear Logs
        </button>
      </div>
    </div>
  );
};
```

